# Rescan terminators with a looser stem (>=6) and any T-run >=4 in the 9 nt downstream,
# anywhere in the molecule, to see general background, then compare near ends.
def find_terminators(seq, min_stem=6, min_tail_T=4):
    hits=[]
    L=len(seq)
    for i in range(L-2*min_stem-3):
        best=None
        for stem in range(10, min_stem-1, -1):
            if i+2*stem+3 > L: continue
            left = seq[i:i+stem]
            right = seq[i+stem+3:i+stem+3+stem]
        # treat loop lengths 3..8
        for stem in range(min_stem, 11):
            for loop in range(3,9):
                if i+stem*2+loop+9 > L: continue
                left = seq[i:i+stem]
                right = seq[i+stem+loop:i+stem+loop+stem]
                rc = right.translate(str.maketrans('ACGT','TGCA'))[::-1]
                if left == rc or left[:-1] == rc[1:] and False:
                    mism=0
                    for a,b in zip(left, rc):
                        if a!=b: mism+=1
                    if mism <= 0:
                        tail = seq[i+stem*2+loop:i+stem*2+loop+9]
                        if tail.count('T')>=min_tail_T:
                            hits.append((i+1, stem, loop, tail, mism))
    # dedup by start
    seen=set(); unique=[]
    for h in sorted(hits, key=lambda x:-x[1]):
        if h[0] not in seen:
            seen.add(h[0]); unique.append(h)
    return unique

hits = find_terminators(s)
print("All perfect stem-loop+T-tail structures (any location):", len(hits))
for h in hits:
    print(f"  pos {h[0]:<6} stem={h[1]:<3} loop={h[2]:<3} tail={h[3]} mism={h[4]}")
print("\nNear ends (first 300 or last 300 nt):")
for h in hits:
